using static StrataLint.Scribe.DefinitionDsl;
namespace StrataLint.Scribe.Blueprint.D5.S3.Arith.Congruence;
internal sealed class HannaUniformCorrectionDocument : IScribeDocumentDefinition
{
    private const string Prefix = "D5/S3/Arith/Congruence/HannaUniformCorrection.";
    public DocumentDefinition Create() => DocumentDefinition.Create(ScribeNode.Create(
        "The complete uniform corrected-Euler power family", H("The complete uniform corrected-Euler power family"), Blocks(
            Paragraph(Text("The parameter s is an integer. The contract uses all s>=2 and every positive natural index. The internal integer weight uses s.toNat; weight_cast proves equality with the requested rational integer power for every s>=0, including zero. All appearances of s.toNat-1 and s.toNat*(r-1)-r represent the corresponding nonnegative integer exponents on their stated domains. The actual F is exp(sum over n>=1 of (n^s-a_s(n))*X^n/n). Its integer coefficients f are extracted independently from the canonical Euler series and then identified with the actual rational coefficients. Su, Theorems 7.1-7.2, owns the known square-weight conclusions; the supplied 4 November 2026 note by Haobo Ma and Wenlin Zhang motivates the uniform extension. Literature novelty of the all-s extension is unverified. Bala owns the cited universal-shift theorem for A082579, which is outside this module.")),
            Node("weight", "weight", "The integer recursion uses the natural representative of the nonnegative integer weight. Negative parameters are not asserted to model negative-power integrality.", DescribeRole.Definition),
            Node("a", "a", "The correction is the generic bounded residue for the integer power weight.", DescribeRole.Definition),
            Node("c", "c", "The positive-index Euler exponents are the generic recursively constructed integer ledger.", DescribeRole.Definition),
            Node("F", "F", "This is the literal rational formal exponential with integer power parameter s. Its logarithmic input has constant coefficient zero.", DescribeRole.Definition),
            Node("IsPowerCorrection", "IsPowerCorrection", "The predicate states exactly the positive-index bounds and integrality of that literal exponential, with no prescribed value at zero.", DescribeRole.Definition),
            Node("weight_cast", "weight cast", "For every nonnegative integer s and every natural n, the cast integer weight is exactly the rational integer power n^s. This discharges the domain correspondence.", DescribeRole.Theorem),
            Node("correction_spec", "correction spec", "The generic integer-weight construction supplies boundedness and actual exponential integrality.", DescribeRole.Theorem),
            Node("correction_exists_unique", "correction exists unique", "Existence and uniqueness hold on every positive index for every integer s>=0. Whole-function uniqueness is deliberately absent because the entry at zero is unused.", DescribeRole.Theorem),
            Paragraph(Text("For s>=0, map_Z_to_Q(eulerSeries(i ↦ c_s(i+1)))=F_s. Apply HannaDiagonalGhostPowerIntegrality.euler_series_exponential with the positive-index identity weight(s,n)-a_s(n)=divisorGhost(c_s,n), supplied by BoundedEulerCorrection.correction_equation. At divisors d>0, (d-1)+1=d. The integer Euler object has HasProd by HannaDiagonalGhostPowerIntegrality.hasProd_eulerSeries; this is an actual infinite product.")),
            Node("correction_prime_power", "correction prime power", "The generalized original owner induction treats every prime including two and every positive power. At the first prime power the representative is p-1; at higher powers both weights vanish modulo p^r because s>=2.", DescribeRole.Theorem),
            Node("exponent_prime", "exponent prime", "Subtracting actual divisor ghosts at p and one gives p*c_s(p)=p^s-p. Integer cancellation yields p^(s-1)-1.", DescribeRole.Theorem),
            Node("exponent_bounds", "exponent bounds", "Prime indices use exponent_prime directly. On composite indices, strong induction bounds the proper-divisor ghost between zero and the proper-divisor power sum. The additive-n divisor budget and the correction interval force the new exponent to be a positive integer, at most n^(s-1).", DescribeRole.Theorem),
            Paragraph(Text("For every integer s>=2, every prime p including 2, and r>=1, a_s(p^r)=p-1. Apply HannaPrimePowerCorrection.bounded_power_corrections with exponent s.toNat. Its interval premise is correction_spec; its divisibility premise follows from divisor_ghost_gauss(c_s) and correction_equation at consecutive prime powers.")),
            Paragraph(Text("For every s>=2 and prime p, c_s(p)=p^(s.toNat-1)-1. Subtract divisorGhost(c_s,1) from divisorGhost(c_s,p). The difference is p*c_s(p); a_s(1)=0 and a_s(p)=p-1. Thus p*c_s(p)=p^s-p, and cancellation by the positive integer p gives the formula.")),
            Paragraph(Text("For every s>=2, prime p and r>=2, c_s(p^r)=p^(s.toNat*(r-1)-r)*(p^s.toNat-1). Consecutive prime-power divisor ghosts differ by p^r*c_s(p^r); the corrections are both p-1. Their difference is therefore p^(r*s.toNat)-p^((r-1)*s.toNat). Since r<=s.toNat*(r-1), factor and cancel the nonzero p^r. No negative natural exponent is used.")),
            Node("f", "f", "These are ordinary integer coefficients of the canonical Euler series. They are not defined by a recurrence or a requested partition count.", DescribeRole.Definition),
            Paragraph(Text("For s>=0 and every n>=0, (f_s(n):Q)=coeff_n(F_s), by applying coeff_n to the Euler/exponential equality and using coeff_map. The integers f are extracted from the existing Euler series independently of this equality.")),
            Node("ColouredPartition", "ColouredPartition", "The independent finite generic coloured carrier is specialized to (c_s(d)).toNat. Positive-index exponent bounds prove this natural colour count faithfully equals the integer exponent at every occurring part.", DescribeRole.Definition),
            Paragraph(Text("For s>=2 and n>=0, f_s(n)=Nat.card(ColouredPartition(s,n)). The exponent bound gives c_s(d)>=1 at d>0, so Int.toNat_of_nonneg identifies c_s(d) with its natural colour count. Substitute this into ColouredEulerLedger.coloured_coefficient. The generic finite carrier includes zero colours and degree zero; the latter has the unique empty partition.")),
            Paragraph(Text("For every integer s, f_s(0)=1. At degree zero, the defining Euler series is ledgerProduct at the empty prefix; its constant coefficient is one.")),
            Paragraph(Text("For s>=0 and n>=0, n*f_s(n)=sum_{k=0}^{n-1}((k+1)^s.toNat-a_s(k+1))*f_s(n-(k+1)). Apply EulerExponentialCoefficients.coefficient_recurrence to g(n)=weight(s,n)-a_s(n), use weight_cast and the Euler/exponential coefficient equality, and reflect the rational equality through the injective integer cast. The n=0 sum is empty.")),
            Paragraph(Text("For s>=2, f_s(n)>0 for every n>=0. On positive indices m, m^s>=m>a_s(m), so g(m)=m^s-a_s(m)>0. Apply EulerExponentialCoefficients.coefficient_positive and transport through the actual coefficient equality; degree zero is one.")),
            Paragraph(Text("For s>=2, f_s is nondecreasing on all natural indices. The first corrected ghost is g(1)=1. For n>=1, write m^s=m*m^(s-1), use n^(s-1)<=(n+1)^(s-1) and (n+1)^(s-1)>=n+1 to get (n+1)^s-n^s>=n+1. Together with 0<=a_s(n)<n and 0<=a_s(n+1)<n+1 this gives g(n)<=g(n+1). EulerExponentialCoefficients.coefficient_monotone then applies, followed by coefficient transport.")),
            Node("correction_boundary", "correction boundary", "At weights zero and one, the bounded positive-index corrections are respectively zero and n-1. Their literal corrected ghosts equal one. Uniqueness comes from the same generic construction.", DescribeRole.Theorem),
            Node("F_boundary", "F boundary", "Both actual boundary exponentials equal the inverse of one minus X. Coefficient induction proves exp(sum X^n/n) has every coefficient one; the formal geometric-series identity identifies its inverse. At weight one and prime-square index p^2, the correction is p^2-1, so the constant prime-power formula starts at weight two. For J_s(n)=sum over d dividing n of mu(n/d)*d^s, the generic Mobius identity at weight(s) gives n*c_s(n)=J_s(n)-sum over d dividing n of mu(n/d)*a_s(d). The generic logarithmic estimate at the same weight gives |c_s(n)-J_s(n)/n|<=1+log(n) for every positive n.", DescribeRole.Theorem))));
    private static DocumentBlock Node(string name, string title, string prose, DescribeRole role) =>
        Describe.Lean(DescribeId.Create("hannauniformcorrection-" + (name == "F" ? "formal-exponential" : name.ToLowerInvariant().Replace("_", "-"))),
            DeclarationHandle.Create(Prefix + name), H(title), StatementSource.WithoutFormula(),
            AssessedProvenance.FromRepo(), Blocks(Paragraph(Text(prose))), role);
}
